describe('Currency Field Formatting', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should format currency input with commas and two decimal places on blur', () => {
    // Intercept the API call to validate currency format
    cy.intercept('POST', '/api/validate-currency').as('validateCurrency');

    // Get the currency input field
    cy.get('[data-testid="currency-input"]').type('1234567.89');

    // Focus on the input field
    cy.get('[data-testid="currency-input"]').focus();

    // Blur the input field
    cy.get('[data-testid="currency-input"]').blur();

    // Wait for the API validation
    cy.wait('@validateCurrency');

    // Verify the formatted value is displayed
    cy.get('[data-testid="formatted-currency-value"]').should('be.visible');
    cy.get('[data-testid="formatted-currency-value"]').should('contain', '1,234,567.89');

    // Verify the original value is still in the input
    cy.get('[data-testid="currency-input"]').should('have.value', '1234567.89');
  });

  it('should not format currency input when it is not a valid number', () => {
    // Intercept the API call to validate currency format
    cy.intercept('POST', '/api/validate-currency').as('validateCurrency');

    // Get the currency input field
    cy.get('[data-testid="currency-input"]').type('abc123');

    // Focus on the input field
    cy.get('[data-testid="currency-input"]').focus();

    // Blur the input field
    cy.get('[data-testid="currency-input"]').blur();

    // Wait for the API validation
    cy.wait('@validateCurrency');

    // Verify the formatted value is not displayed
    cy.get('[data-testid="formatted-currency-value"]').should('not.exist');

    // Verify the original value is still in the input
    cy.get('[data-testid="currency-input"]').should('have.value', 'abc123');
  });
});
